-//  C = clamp(round(512 + 896 C′), 0, 1023), C′ the block's mean.
+//  C = clamp(round(512 + 896 C′), 0, 1023), C′ the block's mean; at 8 bits
+//  Y = round(16 + 219 Y′) and C = clamp(round(128 + 224 C′), 0, 255).
