-//  CX-14 (3)): a compositor frame (64RGBAHalf, premultiplied, in the encoding
-//  of the picture the export writes) converted to video-range 10-bit I010 in
-//  three planes of one buffer, each sample 16 bits, little-endian, the 10 bits
-//  in its low bits (yuv420p10le). Owned by `app/Sources/ExportI010.swift`,
-//  which scales the frame to the export size first when it is not the canvas.
+//  ExportI010.metal — the bundled encoders' frames (spec §11 CX-12 (5),
+//  CX-14 (3), CX-16 (3)): a compositor frame (64RGBAHalf, premultiplied, in the
+//  encoding of the picture the export writes) converted to video-range 10-bit
+//  I010 in three planes of one buffer, each sample 16 bits, little-endian, the
+//  10 bits in its low bits (yuv420p10le) — the AV1 rows', and `vp9_webm`'s at
+//  HLG and PQ — or, by `framejob_export_i420`, to video-range 8-bit I420, each
+//  sample one byte (yuv420p) — `vp9_webm`'s SDR picture. Owned by
+//  `app/Sources/ExportI010.swift`, which scales the frame to the export size
+//  first when it is not the canvas.
 //
 //  One thread per 2 × 2 block: it writes the block's four luma samples and
 //  one Cb and one Cr, the mean of the four pixels' (a 2 × 2 box, the chroma
@@ -15,7 +18,8 @@
 //  The matrix is the picture's (`kr`, `kb`: BT.709's or BT.2020's):
 //  Y′ = kr R + (1 − kr − kb) G + kb B; Cb′ = (B − Y′) / (2 (1 − kb));
 //  Cr′ = (R − Y′) / (2 (1 − kr)); Y = round(64 + 876 Y′);
-//  C = clamp(round(512 + 896 C′), 0, 1023), C′ the block's mean.
+//  C = clamp(round(512 + 896 C′), 0, 1023), C′ the block's mean; at 8 bits
+//  Y = round(16 + 219 Y′) and C = clamp(round(128 + 224 C′), 0, 255).
 //

 #include <metal_stdlib>
@@ -65,3 +69,37 @@ kernel void framejob_export_i010(texture2d<half, access::read> src [[texture(0)]
     planes[u.cbOffset + chroma] = ushort(clamp(round(512.0 + 896.0 * cb / count), 0.0, 1023.0));
     planes[u.crOffset + chroma] = ushort(clamp(round(512.0 + 896.0 * cr / count), 0.0, 1023.0));
 }
+
+/// The same block at 8 bits (spec §11 CX-16 (3)): one byte a sample, the
+/// strides and offsets in samples as above.
+kernel void framejob_export_i420(texture2d<half, access::read> src [[texture(0)]],
+                                 device uchar *planes [[buffer(0)]],
+                                 constant ExportI010Uniforms &u [[buffer(1)]],
+                                 uint2 gid [[thread_position_in_grid]]) {
+    if (gid.x * 2 >= u.width || gid.y * 2 >= u.height) {
+        return;
+    }
+    const float3 weights = float3(u.kr, 1.0 - u.kr - u.kb, u.kb);
+    const float cbScale = 2.0 * (1.0 - u.kb);
+    const float crScale = 2.0 * (1.0 - u.kr);
+    float cb = 0.0;
+    float cr = 0.0;
+    float count = 0.0;
+    for (uint dy = 0; dy < 2; dy++) {
+        for (uint dx = 0; dx < 2; dx++) {
+            uint2 at = uint2(gid.x * 2 + dx, gid.y * 2 + dy);
+            if (at.x >= u.width || at.y >= u.height) {
+                continue;
+            }
+            float3 rgb = clamp(float3(src.read(at).rgb), 0.0, 1.0);
+            float luma = dot(rgb, weights);
+            planes[at.y * u.lumaStride + at.x] = uchar(round(16.0 + 219.0 * luma));
+            cb += (rgb.b - luma) / cbScale;
+            cr += (rgb.r - luma) / crScale;
+            count += 1.0;
+        }
+    }
+    uint chroma = gid.y * u.chromaStride + gid.x;
+    planes[u.cbOffset + chroma] = uchar(clamp(round(128.0 + 224.0 * cb / count), 0.0, 255.0));
+    planes[u.crOffset + chroma] = uchar(clamp(round(128.0 + 224.0 * cr / count), 0.0, 255.0));
+}
